<script lang="ts">
 import {enhance} from '$app/forms';
 import {onMount} from 'svelte';
 let interactive=$state(false);onMount(()=>{interactive=true;});
 import {weatherDays,celsius,weatherKind} from './weather.mjs';
 import WeatherIcon from './WeatherIcon.svelte';
 import WeatherPeriods from './WeatherPeriods.svelte';
 let view=$state('weekly');
 let {zone,cached,products,enhanced,busy}:{zone:any,cached:any,products:any,enhanced:any,busy:boolean}=$props();
 let payload=$derived(cached?.data||products.getForecastWeather?.value);
 let days=$derived(weatherDays(payload));
 let current=$derived(payload?.normal?.current||payload?.current||products.getPresentWeather?.value?.normal?.current||products.getPresentWeather?.value?.current);
 let retrieved=$derived(cached?.fetched_at||products.getForecastWeather?.fetchedAt);
 let limits=$derived(days.flatMap((d:any)=>[d.min,d.max]).filter((v:number|null):v is number=>v!==null));
 let low=$derived(limits.length?Math.min(...limits)-3:0),high=$derived(limits.length?Math.max(...limits)+3:1);
 const y=(v:number)=>140-(v-low)/(high-low)*105;
 const x=(i:number)=>35+i*80;
 const date=(dt:number,short=false)=>new Date(dt*1000).toLocaleDateString('en-GB',{weekday:'short',...(short?{}:{day:'numeric',month:'short'}),timeZone:'Africa/Harare'});
 const reading=(n:number|null)=>n===null?'Unavailable':`${Math.round(n)}\u00b0`;
 const amount=(n:number|null,unit:string)=>n===null?'Unavailable':`${n.toLocaleString('en',{maximumFractionDigits:2})}${unit}`;
 let rainTotal=$derived(days.reduce((sum:number,d:any)=>sum+(d.rain??0),0));
 let rainComplete=$derived(days.every((d:any)=>d.rain!==null));
</script>
<section class="p-card weather-intro"><div><p class="p-kicker">FIELD WEATHER / {zone.name}</p><h2>A clearer outlook for your land.</h2><p>Seven-day forecast for the centre of your mapped field.</p></div><form method="POST" action="?/weather" use:enhance={enhanced}><input type="hidden" name="zone" value={zone.id}/><button class="p-button" disabled={busy}>{busy?'Refreshing forecast…':days.length?'Refresh forecast':'Load field forecast'}</button></form></section>
{#if days.length}
 <div class="weather-views" role="group" aria-label="Forecast view">{#each [["daily","Daily"],["weekly","Weekly"],["monthly","Monthly"]] as [id,label]}<button type="button" disabled={!interactive} class:chosen={view===id} aria-pressed={view===id} onclick={()=>view=id}>{label}</button>{/each}</div>
 <WeatherPeriods {days} {payload} {view}/>
 {#if view==='weekly'}
 <section class="weather-board" aria-label="Weather overview"><div class="weather-now"><p class="p-kicker">{current?'CURRENT CONDITIONS':'FIRST FORECAST DAY'}</p><div class="now-reading"><strong>{current?reading(celsius(current.temp)):reading(days[0].max)}<small>C</small></strong><div class="hero-icon"><WeatherIcon kind={current?weatherKind(current.weather?.[0]):days[0].icon}/></div></div><h3>{current?.weather?.[0]?.description||days[0].description}</h3><p>{zone.name} <span> / {date(current?.dt||days[0].timestamp)}</span></p><div class="rain-summary"><span class="mini-icon"><WeatherIcon kind="drop"/></span><div><strong>{rainComplete?amount(rainTotal,' mm'):'Unavailable'}</strong><small>Forecast rainfall across {days.length} days</small></div></div></div>
 <div class="weather-chart"><div class="chart-heading"><p class="p-kicker">THE WEEK AHEAD / °C</p><span><i></i>High <i class="low"></i>Low</span></div><svg viewBox="0 0 550 185" role="img" aria-label="Daily high and low temperature forecast. Exact values are listed below.">{#each [45,90,140] as line}<path d={`M20 ${line}H535`} stroke="#ffffff18"/>{/each}{#each ['max','min'] as key}{#each days as d,i}{@const v=d[key as 'max'|'min']}{@const prev=i?days[i-1][key as 'max'|'min']:null}{#if i&&v!==null&&prev!==null}<line x1={x(i-1)} y1={y(prev)} x2={x(i)} y2={y(v)} stroke={key==='max'?'#d7e99b':'#83bac6'} stroke-width="2.5" stroke-dasharray={key==='min'?'4 5':undefined}/>{/if}{#if v!==null}<circle cx={x(i)} cy={y(v)} r="3.5" fill={key==='max'?'#d7e99b':'#83bac6'}/><text x={x(i)} y={y(v)+(key==='max'?-12:20)} text-anchor="middle">{Math.round(v)}°</text>{/if}{/each}{/each}{#each days as d,i}<text x={x(i)} y="180" text-anchor="middle">{date(d.timestamp,true)}</text>{/each}</svg><p class="retrieved">Updated {retrieved?new Date(retrieved).toLocaleString('en-GB',{timeZone:'Africa/Harare'}):'time unavailable'} · Talazo weather</p></div></section>
 <div class="forecast-heading"><h2>Your daily forecast</h2><p>Temperature, rainfall and field conditions at a glance.</p></div>
 <div class="weather-days">{#each days as day,i}<article class="forecast-day" class:first={i===0}><div class="day-heading"><p class="p-kicker">{date(day.timestamp)}</p>{#if i===0}<span>First day</span>{/if}</div><div class="day-icon"><WeatherIcon kind={day.icon}/></div><h3>{day.description}</h3><div class="temps"><strong>{reading(day.max)}</strong><span>{reading(day.min)}<small>High / low °C</small></span></div><dl>{#each [['Chance of rain',day.probability,'%', 'drop'],['Rainfall',day.rain,' mm','rain'],['Wind',day.wind,' m/s','wind'],['Humidity',day.humidity,'%', 'drop']] as [label,value,unit,icon]}<div><dt><span class="metric-icon"><WeatherIcon kind={String(icon)}/></span>{label}</dt><dd>{amount(value as number|null,String(unit))}</dd></div>{/each}</dl><div class="rain-track" aria-hidden="true"><span style:width={`${day.probability??0}%`}></span></div></article>{/each}</div>
 {/if}
 <p class="weather-note">Forecasts are estimates and can vary across your farm. Rainfall is shown as 0 mm when the weather feed omits the optional rain amount; missing or invalid measurements remain unavailable.</p>
{:else}<section class="p-card p-empty"><div class="empty-icon"><WeatherIcon kind="sun"/></div><h2>Your forecast starts with this field.</h2><p>Load the forecast above. Weather is available before satellite monitoring is approved.</p></section>{/if}
<style>
.weather-views{display:flex;gap:6px;margin-bottom:22px;padding:5px;border:1px solid #dce4d3;border-radius:10px;width:fit-content;background:#eef2e5}.weather-views button{border:0;border-radius:7px;padding:12px 24px;background:transparent;color:#214c38;font:inherit;font-size:13px;font-weight:600}.weather-views button.chosen{background:#174a38;color:#fff}

.weather-intro{display:flex;align-items:center;justify-content:space-between;gap:24px}.weather-intro p{margin-bottom:0}.weather-board{display:grid;grid-template-columns:minmax(250px,1fr) minmax(0,1.7fr);gap:40px;padding:32px;background:#123f33;color:#f7faee;border-radius:18px;margin-bottom:32px}.weather-board .p-kicker{color:#c9dcae}.now-reading{display:flex;align-items:center;gap:24px}.now-reading>strong{font-size:76px;font-weight:500;line-height:1.2;letter-spacing:-4px}.now-reading small{font-size:24px;letter-spacing:0}.hero-icon{width:88px;height:88px;color:#c6dadd}.weather-now h3{text-transform:capitalize;font-size:21px;margin:10px 0}.weather-now>p:not(.p-kicker){font-size:13px}.weather-now>p span{color:#c1d0c3}.rain-summary{display:flex;gap:12px;border-top:1px solid #ffffff25;padding-top:18px;margin-top:24px}.rain-summary strong{font-size:21px}.rain-summary small{display:block;color:#c1d0c3;font-size:11px;margin-top:4px}.mini-icon{width:36px;height:36px;color:#93c1cd}.weather-chart{align-self:center;min-width:0}.chart-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.chart-heading>span{display:flex;align-items:center;gap:8px;font-size:11px;white-space:nowrap}.chart-heading i{width:14px;height:3px;background:#d7e99b}.chart-heading i.low{background:#83bac6}.weather-chart svg{display:block;width:100%;overflow:visible}.weather-chart text{fill:#eff5df;font-size:11px}.retrieved{font-size:10px;color:#c1d0c3;margin:18px 0 0}.forecast-heading{display:flex;gap:20px;justify-content:space-between;align-items:baseline;margin-bottom:18px}.forecast-heading h2{font-size:24px;margin:0}.forecast-heading p{font-size:13px;color:#687865;margin:0}.weather-days{display:grid;grid-template-columns:repeat(auto-fit,minmax(225px,1fr));gap:14px}.forecast-day{min-width:0;background:#fffef9;border:1px solid #dce4d3;border-radius:14px;padding:22px}.forecast-day.first{background:#edf2e3;border-color:#c2d3af}.day-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:26px}.day-heading .p-kicker{font-size:10px;letter-spacing:.12em;margin:0}.day-heading>span{font-size:9px;white-space:nowrap;color:#436444}.day-icon{width:64px;height:64px;color:#77989a;margin:18px 0 10px}.forecast-day h3{font-size:17px;text-transform:capitalize;margin:0;min-height:48px;line-height:1.4}.temps{display:flex;align-items:center;gap:14px;padding:16px 0 22px}.temps strong{font-size:40px;letter-spacing:-2px;font-weight:500;line-height:1.1}.temps>span{font-size:18px;color:#687865}.temps small{display:block;font-size:9px;margin-top:3px}dl{margin:0;border-top:1px solid #dce4d3}dl>div{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:10px;min-height:44px;border-bottom:1px solid #e8ecdf}dt{margin:0;display:flex;align-items:center;gap:7px;font-size:11px;color:#63745e;white-space:nowrap}dd{margin:0;text-align:right;font-size:12px;font-weight:600;font-variant-numeric:tabular-nums;white-space:nowrap;align-self:center}.metric-icon{display:block;width:18px;height:18px;color:#77989a;flex-shrink:0}.rain-track{height:4px;background:#dfe7d7;border-radius:4px;margin-top:18px;overflow:hidden}.rain-track span{display:block;height:100%;background:#6c9caf}.weather-note{font-size:11px!important;color:#687865;margin:20px 0!important;line-height:1.7}.empty-icon{width:64px;height:64px;margin:0 auto 18px}@media(min-width:1800px){.weather-days{grid-template-columns:repeat(7,minmax(0,1fr))}.forecast-day{padding:18px}dt{font-size:10px}}@media(max-width:900px){.weather-board{grid-template-columns:1fr;gap:28px}.weather-intro{align-items:start;flex-direction:column}.weather-now{max-width:440px}.forecast-heading{display:block}.forecast-heading p{margin-top:8px}}@media(max-width:540px){.weather-board{padding:22px}.now-reading>strong{font-size:64px}.weather-days{grid-template-columns:1fr}.forecast-day{padding:22px}.day-icon{float:right;margin:15px 0}.forecast-day h3{padding-top:22px;min-height:48px}.temps{padding-top:10px}.chart-heading{flex-wrap:wrap}.weather-chart text{font-size:12px}}
</style>
